by-created-by.map:
function(doc) {
    var defaults = {
      _id: null,
      _rev: null,
      offline_ids: null,
      offline_key: null,
      offline_state: null,
      case_documents: null,
      created_by: null,
      date_created: null,
      last_updated_by: null,
      date_last_updated: null
    };
    emit(doc.created_by, {
      _id: doc._id,
      _rev: doc._rev,
      offline_ids: doc.offline_ids,
      offline_key: doc.offline_key,
      offline_state: doc.offline_state,
      case_documents: doc.case_documents,
      created_by: doc.created_by,
      date_created: doc.date_created,
      last_updated_by: doc.last_updated_by,
      date_last_updated: doc.date_last_updated
    });
}
